#define BLOCK_BUILD_NS_PER_PLAYER_DEFINED
static const double block_build_ns_per_player[6] = {
    5.3362,  /* B=8  */
    6.0105,  /* B=16 */
    6.4528,  /* B=24 */
    6.5732,  /* B=32 */
    7.5059,  /* B=48 */
    8.7667   /* B=64 */
};
#endif

